    m = max((abs(amp * (math.sin(2 * math.pi * (i + 1) / nx + phase) - math.sin(2 * math.pi * i / nx + phase))) / (lx / nx) for i in range(nx)))
    return 1.0 / math.sqrt(1.0 + m * m)

